tools.usage:
host -> {action: 'remoteInvokeReady'}
editor -> {action: 'remoteInvoke', functionName: 'getFile', functionArgs: ['id'], ...}
host -> {action: 'remoteInvokeResponse', resp: [...], error: null}

tools.example:
window.addEventListener('message', e => {
  const m = JSON.parse(e.data);
  if (m.action === 'remoteInvoke' && m.functionName === 'getCurrentUser') {
    e.source.postMessage(JSON.stringify({action: 'remoteInvokeResponse', resp: [{name: 'Ada'}], msgMarkers: m.msgMarkers}), '*');
  }
});

